402	    @Test
403	    void concurrentGrantsProduceSingleEpoch() throws Exception {
404	        int threads = 8;
405	        ExecutorService pool = Executors.newFixedThreadPool(threads);
406	        CountDownLatch ready = new CountDownLatch(threads);
407	        CountDownLatch start = new CountDownLatch(1);
408	        List<Callable<Integer>> tasks = new ArrayList<>();
409	        for (int i = 0; i < threads; i++) {
410	            String requestId = "g-concurrent-" + i;
411	            tasks.add(() -> {
412	                ready.countDown();
413	                start.await();
414	                return consentService.grant(
415	                        new com.example.starter.consent.dto.GrantRequest(requestId, "subj-c", Purpose.RESEARCH)).epoch();
416	            });
417	        }
418	        List<Future<Integer>> futures = new ArrayList<>();
419	        for (Callable<Integer> task : tasks) {
420	            futures.add(pool.submit(task));
421	        }
422	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
423	        start.countDown();
424	        for (Future<Integer> future : futures) {
425	            assertThat(future.get(20, TimeUnit.SECONDS)).isEqualTo(1);
426	        }
427	        pool.shutdown();
428	        assertThat(count("SELECT COUNT(*) FROM consent_grant WHERE subject_key = 'subj-c'")).isEqualTo(1);
429	    }
