package com.example.starter.consent;

/**
 * 接收方证明版本状态：ACTIVE 生效；SUPERSEDED 已被续签新版本取代；REVOKED 已撤销。
 * 同一接收方＋用途＋代次任一时刻至多一条 ACTIVE。
 */
public enum AttestationStatus {
    ACTIVE,
    SUPERSEDED,
    REVOKED
}

package com.example.starter.consent.dto;

import java.time.Instant;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 接收方证明提交/续签请求：为“接收方＋用途＋代次”提交一条新版本证明。
 *
 * @param attestKey       幂等键，指纹含接收方、用途代次、到期与声明摘要；同键同参重放首次响应，失败不占键
 * @param recipientId     数据接收方标识
 * @param purpose         用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch           证明适用的授权代次，精确匹配，不可跨代复用
 * @param expiresAt       UTC 到期时刻，必须晚于提交时刻
 * @param statementDigest 声明摘要（合成字符串）
 */
public record AttestRequest(
        @NotBlank @Size(max = 128) String attestKey,
        @NotBlank @Size(max = 128) String recipientId,
        @NotNull Purpose purpose,
        @NotNull Integer epoch,
        @NotNull Instant expiresAt,
        @NotBlank @Size(max = 256) String statementDigest) {
}

package com.example.starter.consent.dto;

import java.time.Instant;

import com.example.starter.consent.AttestationStatus;
import com.example.starter.consent.Purpose;

/**
 * 接收方证明响应：返回证明的一个版本及其当前状态。
 *
 * @param recipientId     数据接收方标识
 * @param purpose         用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch           证明适用的授权代次
 * @param version         证明版本，同一接收方＋用途＋代次内从 1 开始递增
 * @param expiresAt       UTC 到期时刻
 * @param statementDigest 声明摘要
 * @param status          状态：ACTIVE 生效 / SUPERSEDED 已被续签取代 / REVOKED 已撤销
 */
public record AttestationResponse(
        String recipientId,
        Purpose purpose,
        int epoch,
        int version,
        Instant expiresAt,
        String statementDigest,
        AttestationStatus status) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 证明撤销请求：撤销“接收方＋用途＋代次”的当前生效证明，仅影响后续查询，不改写已生成快照。
 *
 * @param requestId   幂等请求标识，同一 requestId 相同参数重试返回原结果
 * @param recipientId 数据接收方标识
 * @param purpose     用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch       授权代次
 */
public record AttestRevokeRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String recipientId,
        @NotNull Purpose purpose,
        @NotNull Integer epoch) {
}

package com.example.starter.consent.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 接收方整体禁用请求：禁用后该接收方所有新批次查询返回 403，即使证明仍有效。
 *
 * @param requestId   幂等请求标识，同一 requestId 相同参数重试返回原结果
 * @param recipientId 数据接收方标识
 */
public record RecipientDisableRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String recipientId) {
}

package com.example.starter.consent.dto;

/**
 * 接收方状态响应。
 *
 * @param recipientId 数据接收方标识
 * @param status      状态：ACTIVE 正常 / DISABLED 已整体禁用
 */
public record RecipientStatusResponse(String recipientId, String status) {
}

package com.example.starter.consent.dto;

import java.util.List;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 批量数据查询创建请求：所有目标主体的当前授权代次均须存在该接收方未到期证明，
 * 任一缺失或已到期则整次 403，不返回任何部分数据。
 *
 * @param recipientId 数据接收方标识
 * @param purpose     查询用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param subjectKeys 目标数据主体标识列表（去重后按字典序稳定处理）
 */
public record BatchQueryRequest(
        @NotBlank @Size(max = 128) String recipientId,
        @NotNull Purpose purpose,
        @NotEmpty List<@NotBlank @Size(max = 128) String> subjectKeys) {
}

package com.example.starter.consent.dto;

import java.util.List;

import com.example.starter.consent.Purpose;

/**
 * 批量数据查询快照响应：创建后不可改写，后续证明撤销、授权撤回均不影响本快照内容。
 *
 * @param batchId     批次查询标识
 * @param recipientId 发起查询的数据接收方标识
 * @param purpose     查询用途
 * @param items       逐主体快照，按主体标识字典序稳定排列
 */
public record BatchQueryResponse(
        long batchId,
        String recipientId,
        Purpose purpose,
        List<Item> items) {

    /**
     * 单主体快照：记录查询时的授权代次、所用证明版本与记录内容。
     *
     * @param subjectKey         主体标识
     * @param epoch              查询时主体的当前授权代次
     * @param attestationVersion 门禁校验所用的证明版本
     * @param records            该主体当前代次的记录快照
     */
    public record Item(String subjectKey, int epoch, int attestationVersion, List<RecordView> records) {
    }

    /**
     * 快照中的单条记录。
     *
     * @param recordKey 记录键
     * @param payload   记录内容
     */
    public record RecordView(String recordKey, String payload) {
    }
}

