        createBatch("rcp-1", "RESEARCH", "subj-a")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items[0].epoch").value(2))
                .andExpect(jsonPath("$.items[0].attestationVersion").value(1));
