    // ---------- 撤销与快照不可改写 ----------

    @Test
    void revokeAttestationBlocksNewQueriesButKeepsSnapshotUnchanged() throws Exception {
        grant("g-1", "subj-a", "RESEARCH").andExpect(status().isOk());
        write("w-1", "subj-a", "RESEARCH", "rec-1", "payload-a").andExpect(status().isOk());
