                .andExpect(jsonPath("$.violations[0].reason").value("ATTESTATION_MISSING"));

        // 已生成快照及其授权代次、证明版本不可改写
        getBatch(batchId)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items[0].epoch").value(1))
                .andExpect(jsonPath("$.items[0].attestationVersion").value(1))
