        revokeAttest("ar-1", "rcp-1", "RESEARCH", 1).andExpect(status().isOk());
        // 同 requestId 重放返回首次结果
        revokeAttest("ar-1", "rcp-1", "RESEARCH", 1)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("REVOKED"));
