    @Test
    void snapshotRemainsImmutableAfterRegrantAndNewWrites() throws Exception {
        grant("g-1", "subj-a", "RESEARCH").andExpect(status().isOk());
        write("w-1", "subj-a", "RESEARCH", "rec-1", "old-payload").andExpect(status().isOk());
