                .andExpect(status().isOk())
                .andReturn();
        long batchId = batchIdOf(created);

        // 授权换代并写入新数据、证明续签，均不得改写旧快照
        revokeGrant("r-1", "subj-a", "RESEARCH", 1).andExpect(status().isOk());
        grant("g-2", "subj-a", "RESEARCH").andExpect(status().isOk());
